    "faqEyebrow": "सामान्य प्रश्न",
    "faqTitle": "अक्सर पूछे जाने वाले सवाल",
    "faq1Q": "मिस्त्री कितनी जल्दी घर पहुंचेगा?",
    "faq1A": "हमारा स्मार्ट डिस्पैच आपके सबसे नजदीकी मिस्त्री को भेजता है। औसत आगमन समय 30 से 45 मिनट है।",
    "faq2Q": "30-दिन की वारंटी कैसे काम करती है?",
    "faq2A": "काम पूरा होने पर 30-दिन की वारंटी मिलती है। यदि वही समस्या दोबारा आती है, तो मुफ्त में ठीक किया जाएगा।",
    "faq3Q": "क्या सभी मिस्त्री पृष्ठभूमि से जांचे गए हैं?",
    "faq3A": "हाँ, शत-प्रतिशत। प्रत्येक मिस्त्री की सरकारी आईडी, पुलिस जांच और कौशल परीक्षा होती है।",
